import { parseCommandLine } from './argv-parser.mjs';
import { runSourceExecutable } from './executable-runner.mjs';

export function main(argv = process.argv.slice(2)) {
  const parsed = parseCommandLine(argv);

  if (parsed.kind === 'help') {
    writeHelp();
    return parsed.exitCode;
